INSERT INTO "course_nodes" (id, roadmap_id, slug, name, coords, credits, description, created_at, updated_at) VALUES 
(201,2,'academic-english-1','Academic English 1','{"x": 234, "y": 91}',4,'Develops fundamental academic English skills including reading comprehension, academic writing, listening, and speaking. Students learn to interpret academic texts and communicate ideas effectively in an academic environment.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(202,2,'academic-english-2','Academic English 2','{"x": 598, "y": 91}',4,'Builds upon Academic English 1 with advanced skills in essay writing, research-based arguments, presentations, and critical analysis of academic sources.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(203,2,'fundamentals-programming','Fundamentals of Programming','{"x": 234, "y": 507}',4,'Introduces fundamental programming concepts such as variables, control structures, functions, and basic data structures using languages like Python or C++. Emphasizes problem-solving and algorithmic thinking.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(204,2,'calculus-1','Calculus 1','{"x": 234, "y": 407}',4,'Covers limits, continuity, derivatives, and basic integration. Provides mathematical foundations essential for optimization, machine learning, and modeling real-world phenomena.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(205,2,'linear-algebra','Linear Algebra','{"x": 598, "y": 299}',3,'Focuses on vectors, matrices, linear transformations, eigenvalues, and eigenvectors. Essential for machine learning, computer vision, and data representation.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(206,2,'probability-statistics','Probability & Statistics','{"x": 598, "y": 407}',3,'Introduces probability theory, random variables, distributions, expectation, and statistical inference. Forms the backbone of data analysis and machine learning.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(207,2,'discrete-mathematics','Discrete Mathematics','{"x": 598, "y": 515}',4,'Covers logic, set theory, combinatorics, graph theory, and proof techniques. Provides mathematical reasoning for algorithms and computational thinking.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(208,2,'data-structures','Data Structures & Algorithms','{"x": 598, "y": 507}',4,'Studies fundamental data structures (arrays, linked lists, trees, graphs) and algorithms (searching, sorting). Emphasizes efficiency and complexity analysis.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(209,2,'intro-data-science','Introduction to Data Science','{"x": 962, "y": 715}',3,'Provides an overview of the data science lifecycle including data collection, preprocessing, analysis, visualization, and deployment. Introduces common tools such as Python, Pandas, and Jupyter.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(210,2,'data-analysis','Data Analysis','{"x": 1326, "y": 507}',4,'Focuses on exploratory data analysis (EDA), statistical summaries, hypothesis testing, and data interpretation. Uses real-world datasets to extract meaningful insights.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(211,2,'data-visualization','Data Science & Visualization','{"x": 1690, "y": 507}',4,'Teaches principles of visual communication and tools such as Matplotlib, Seaborn, and Tableau to effectively present data insights.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(212,2,'database','Database Management','{"x": 962, "y": 507}',4,'Introduces relational database concepts, SQL querying, normalization, indexing, and transaction management. Essential for managing structured data.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(213,2,'statistical-methods','Statistical Methods','{"x": 962, "y": 731}',3,'Covers advanced statistical techniques including hypothesis testing, ANOVA, and regression foundations for real-world data analysis.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(214,2,'regression-analysis','Regression Analysis','{"x": 962, "y": 839}',4,'Focuses on linear and nonlinear regression models, model assumptions, diagnostics, and predictive modeling techniques.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(215,2,'machine-learning','Machine Learning','{"x": 1326, "y": 299}',4,'Covers supervised and unsupervised learning techniques including regression, classification, clustering, and model evaluation. Introduces algorithms such as decision trees, SVM, and k-means.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(216,2,'data-mining','Data Mining','{"x": 1326, "y": 715}',4,'Explores techniques for discovering patterns and knowledge from large datasets, including association rules, clustering, and anomaly detection.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(217,2,'big-data','Big Data Analysis','{"x": 1690, "y": 715}',4,'Introduces distributed data processing frameworks such as Hadoop and Spark. Covers large-scale data storage, processing, and analytics.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(218,2,'cloud-computing','Cloud Computing','{"x": 1326, "y": 923}',4,'Covers cloud platforms, virtualization, containerization, and scalable deployment of data applications using services like AWS or Azure.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(219,2,'decision-support','Decision Support Systems','{"x": 1690, "y": 923}',4,'Focuses on data-driven decision-making systems, business intelligence tools, and analytical models used in organizations.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(220,2,'deep-learning','Deep Learning','{"x": 2054, "y": 715}',4,'Studies neural networks, CNNs, RNNs, and deep architectures used in image recognition, NLP, and advanced AI systems.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(221,2,'nlp','Natural Language Processing','{"x": 1690, "y": 407}',4,'Focuses on processing and analyzing text data using techniques such as tokenization, embeddings, and transformer-based models.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(222,2,'time-series','Time Series Analysis','{"x": 1690, "y": 515}',4,'Covers methods for analyzing temporal data including ARIMA models, forecasting, and seasonal patterns.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(223,2,'optimization','Optimization','{"x": 1690, "y": 819}',4,'Introduces optimization techniques including linear programming, gradient-based methods, and their applications in machine learning.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(224,2,'project-management','IT Project Management','{"x": 2050, "y": 299}',4,'Covers project planning, scheduling, risk management, and agile methodologies in IT environments.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(225,2,'business-analysis','Business Process Analysis','{"x": 2050, "y": 407}',4,'Focuses on analyzing and improving business processes using data-driven techniques.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(226,2,'information-system','Information System Management','{"x": 2050, "y": 515}',4,'Covers design, implementation, and management of information systems in organizations.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(227,2,'internship','Internship','{"x": 2418, "y": 507}',3,'Provides practical industry experience where students apply data science skills to real-world problems.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(228,2,'thesis','Thesis','{"x": 2782, "y": 507}',10,'Capstone research project involving problem formulation, data analysis, model development, and presentation of findings.','2026-04-16 22:44:22','2026-04-16 22:44:22'),
(301,3,'cs-intro-computing','Introduction to Computing','{"x": 234, "y": 91}',3,'Overview of computer systems, problem solving, and computational thinking.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(302,3,'cs-calculus-1','Calculus 1','{"x": 234, "y": 299}',4,'Limits, derivatives, integrals and mathematical foundations for computing.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(303,3,'cs-physics-1','Physics 1','{"x": 234, "y": 507}',3,'Mechanics and basic physical principles for engineering computing students.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(304,3,'cs-academic-english-1','Academic English 1','{"x": 234, "y": 715}',3,'Fundamental academic English for reading and writing technical content.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(305,3,'cs-calculus-2','Calculus 2','{"x": 598, "y": 299}',4,'Advanced integration, series and multivariable foundations.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(306,3,'cs-linear-algebra','Linear Algebra','{"x": 962, "y": 299}',3,'Vectors, matrices, linear transformations and eigenvalues.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
