(308,3,'cs-programming-fundamentals','Programming Fundamentals','{"x": 598, "y": 507}',4,'Basic programming using C/C++ including control flow, functions and arrays.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(309,3,'cs-discrete-mathematics','Discrete Mathematics','{"x": 962, "y": 507}',4,'Logic, sets, combinatorics, graph theory and proofs.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(310,3,'cs-oop','Object Oriented Programming','{"x": 962, "y": 715}',4,'OOP principles: classes, inheritance, polymorphism and design.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(311,3,'cs-data-structures','Data Structures','{"x": 1326, "y": 715}',4,'Stacks, queues, trees, graphs and complexity analysis.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(312,3,'cs-probability-statistics','Probability & Statistics','{"x": 1326, "y": 299}',3,'Random variables, distributions, expectation and inference.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(313,3,'cs-algorithms','Algorithms','{"x": 1690, "y": 715}',4,'Sorting, searching, dynamic programming and complexity theory.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(314,3,'cs-computer-architecture','Computer Architecture','{"x": 1326, "y": 923}',3,'CPU design, memory hierarchy and instruction execution.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(315,3,'cs-database-systems','Database Systems','{"x": 1326, "y": 507}',4,'SQL, relational model, normalization and indexing.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(316,3,'cs-web-development','Web Development','{"x": 1690, "y": 507}',3,'Frontend and backend fundamentals for web applications.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
(317,3,'cs-operating-systems','Operating Systems','{"x": 1690, "y": 923}',4,'Processes, threads, scheduling, memory management.','2026-04-17 00:34:24','2026-04-17 00:34:24'),
